<?php
use DigiForge\PortalAccess\{Policy,Store,Owner,Session,Invitations};
require_once __DIR__.'/fixtures/PortalAccessFixture.php';
final class PortalAccessTest extends WP_UnitTestCase {
 protected function setUp():void{parent::setUp();PortalAccessFixture::reset();}
 protected function tearDown():void{global $wpdb;$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');parent::tearDown();}
 private function ready():void{self::assertTrue(class_exists(Policy::class),'Portal access policy is not implemented');}
 public function testRoleCeilingsRejectUnknownModulesAndPrimaryOwnerAssignments():void{$this->ready();self::assertWPError(Policy::permissions('Primary Owner',['research']));self::assertWPError(Policy::permissions('Operator',['settings']));self::assertWPError(Policy::permissions('Viewer',['bogus']));self::assertContains('manage_digiforge_research',Policy::permissions('Viewer',['research']));}
 public function testEmailAndWordPressAdministratorAreNotOwnerAuthority():void{$this->ready();PortalAccessFixture::owner();self::assertWPError(Owner::require('personalized_pod'));}
 public function testSignedEnrollmentAndProfileChangePreserveWordPressAccount():void{$this->ready();PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);$before=get_userdata($id)->to_array();$r=Store::change($id,'Viewer',['personalized_pod'=>['research']],true,0,wp_generate_uuid4());self::assertNotWPError($r);self::assertSame($before,get_userdata($id)->to_array());self::assertSame('Viewer',Store::read($id)['role']);}
 public function testDisableAndReenableInvalidateOldDigiForgeSessionOnly():void{$this->ready();$owner=PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);self::assertNotWPError(Store::change($id,'Operator',['personalized_pod'=>['research']],true,0,wp_generate_uuid4()));PortalAccessFixture::login($id);self::assertNotWPError(Session::start());$session=$_COOKIE[Session::name()];$wp=$_COOKIE[LOGGED_IN_COOKIE];self::assertTrue(Session::valid(Store::read($id)));PortalAccessFixture::login($owner);Session::start();self::assertNotWPError(Store::change($id,'Operator',['personalized_pod'=>['research']],false,Store::read($id)['revision'],wp_generate_uuid4()));PortalAccessFixture::login($id);$_COOKIE[Session::name()]=$session;self::assertFalse(Session::valid(Store::read($id)));self::assertTrue(is_user_logged_in());self::assertNotEmpty($wp);}
 public function testDeletedProfileWithRetainedHistoryFailsClosed():void{$this->ready();PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);Store::change($id,'Viewer',['personalized_pod'=>['research']],true,0,wp_generate_uuid4());global $wpdb;$wpdb->delete($wpdb->options,['option_name'=>Store::key($id)]);self::assertWPError(Store::read($id));}
 public function testInvitationIsSubjectBoundExpiringAndSingleUse():void{$this->ready();PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);$invite=Invitations::create($id,'Viewer','personalized_pod',['research'],time()+600,wp_generate_uuid4());self::assertNotWPError($invite);$other=self::factory()->user->create(['role'=>'administrator']);PortalAccessFixture::login($other);self::assertWPError(Invitations::accept($invite['token'],wp_generate_uuid4()));PortalAccessFixture::login($id);self::assertNotWPError(Invitations::accept($invite['token'],wp_generate_uuid4()));self::assertWPError(Invitations::accept($invite['token'],wp_generate_uuid4()));}
 public function testInvitationCannotOutliveOrBypassOwnerAuthority():void{$this->ready();$owner=PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);$invite=Invitations::create($id,'Operator','personalized_pod',['research'],time()+600,wp_generate_uuid4());self::assertNotWPError($invite);PortalAccessFixture::sign($owner,time()-1);PortalAccessFixture::login($id);self::assertWPError(Invitations::accept($invite['token'],wp_generate_uuid4()));}
 public function testReadFailureCannotMasqueradeAsUnmanagedLegacyProfile():void{$this->ready();PortalAccessFixture::enroll();global $wpdb;$prior=$wpdb->suppress_errors(true);$filter=static function($sql){return str_contains($sql,'SELECT option_value')&&str_contains($sql,'digiforge_portal_profile_')?'SELECT * FROM df_missing_profile_read':$sql;};add_filter('query',$filter);try{self::assertWPError(Store::read(self::factory()->user->create(['role'=>'subscriber'])));}finally{remove_filter('query',$filter);$wpdb->suppress_errors($prior);}}
 public function testInvitationExpiresBeforeAcceptanceAndCannotPromoteSubscriber():void{$this->ready();PortalAccessFixture::enroll();$sub=self::factory()->user->create(['role'=>'subscriber']);self::assertWPError(Invitations::create($sub,'Admin','personalized_pod',['research'],time()+60,wp_generate_uuid4()));$id=self::factory()->user->create(['role'=>'administrator']);$r=Invitations::create($id,'Viewer','personalized_pod',['research'],time()+1,wp_generate_uuid4());self::assertNotWPError($r);sleep(2);PortalAccessFixture::login($id);self::assertWPError(Invitations::accept($r['token'],wp_generate_uuid4()));}

 public function testFailedProfilePersistenceCannotLeaveAnUnmanagedNativeGrant():void{$this->ready();PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);$repo=new \DigiForge\Security\ShopAccessRepository();$before=$repo->read('personalized_pod');global $wpdb;$prior=$wpdb->suppress_errors(true);$f=static function($sql)use($id){return str_starts_with($sql,'INSERT ')&&str_contains($sql,Store::key($id))?'SELECT * FROM missing_profile_write':$sql;};add_filter('query',$f);try{self::assertWPError(Store::change($id,'Viewer',['personalized_pod'=>['research']],true,0,wp_generate_uuid4()));}finally{remove_filter('query',$f);$wpdb->suppress_errors($prior);}self::assertSame($before,$repo->read('personalized_pod'));}

}
